{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.inv_l30dS_SKU_level WITH meta_map AS ( SELECT upper(IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) )) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta1 END), MIN(meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta2 END), MIN(meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta3 END), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), sales_b2c AS ( SELECT date, sku_group, SUM(gross_sales::FLOAT) AS revenue, SUM(gross_quantity::INT) AS sales_qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2 ), sales_sor_myntra AS ( SELECT TO_DATE(order_created_date,\'YYYYMMDD\') AS date, style_ sku_group, SUM(TRY_TO_NUMBER(REPLACE(revenue,\',\',\'\'))) AS revenue, SUM(TRY_TO_NUMBER(REPLACE(sales,\',\',\'\'))) AS sales_qty FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date >= 20230101 GROUP BY 1,2 ), sales_sor_flipkart AS ( SELECT TO_DATE(order_date_key,\'YYYYMMDD\') AS date, style_ sku_group, SUM(TRY_TO_NUMBER(REPLACE(sp_per_unit_,\',\',\'\')) * TRY_TO_NUMBER(REPLACE(units,\',\',\'\'))) AS revenue, SUM(TRY_TO_NUMBER(REPLACE(units,\',\',\'\'))) AS sales_qty FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1,2 ), sales_fact AS ( SELECT date, sku_group, SUM(revenue) AS revenue, SUM(sales_qty) AS sales_qty FROM ( SELECT date, sku_group, revenue, sales_qty FROM sales_b2c UNION ALL SELECT date, sku_group, revenue, sales_qty FROM sales_sor_myntra UNION ALL SELECT date, sku_group, revenue, sales_qty FROM sales_sor_flipkart ) GROUP BY 1,2 ), overall_returns_fact AS ( SELECT \"PUTAWAY_UPDATED\"::DATE AS date, upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS overall_returns_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'b2c return%\' GROUP BY 1,2 ), shopify_returns_fact AS ( SELECT order_date::DATE AS date, sku_group, SUM(return_qty) AS shopify_returns_qty FROM snitch_db.maplemonk.return_fact_items WHERE reason NOT IN (\'not_returned\') GROUP BY 1,2 ), inward_fact AS ( SELECT \"PUTAWAY_UPDATED\"::DATE AS date, upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2 ), clicks_fact AS ( SELECT ga_date::DATE AS date, sku_group, SUM(clicks) AS clicks FROM snitch_db.maplemonk.clicks_itemid GROUP BY 1,2 ), inventory_fact AS ( SELECT date, sku_group, SUM( COALESCE(qty_available,0) + COALESCE(qty_offline_available,0) + COALESCE(qty_jit,0) ) AS inventory_qty FROM snitch_db.maplemonk.cogs_daily_snapshot GROUP BY 1,2 ), base_spine AS ( SELECT date, sku_group FROM sales_fact UNION SELECT date, sku_group FROM overall_returns_fact UNION SELECT date, sku_group FROM shopify_returns_fact UNION SELECT date, sku_group FROM inward_fact UNION SELECT date, sku_group FROM clicks_fact UNION SELECT date, sku_group FROM inventory_fact ), daily_grain AS ( SELECT bs.date, bs.sku_group, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, mm.cogs, COALESCE(inv.inventory_qty, 0) AS inventory_qty, COALESCE(inv.inventory_qty, 0) * COALESCE(mm.cogs, 0) AS inventory_cogs_value, COALESCE(sf.revenue, 0) AS revenue, COALESCE(sf.sales_qty, 0) AS sales_qty, COALESCE(sf.sales_qty, 0) * COALESCE(mm.cogs, 0) AS sales_cogs, COALESCE(orf.overall_returns_qty, 0) AS overall_returns_qty, COALESCE(orf.overall_returns_qty, 0) * COALESCE(mm.cogs, 0) AS overall_returns_cogs, COALESCE(srf.shopify_returns_qty, 0) AS shopify_returns_qty, COALESCE(srf.shopify_returns_qty, 0) * COALESCE(mm.cogs, 0) AS shopify_returns_cogs, COALESCE(ifw.inward_qty, 0) AS inward_qty, COALESCE(ifw.inward_qty, 0) * COALESCE(mm.cogs, 0) AS inward_cogs, COALESCE(cf.clicks, 0) AS clicks FROM base_spine bs LEFT JOIN inventory_fact inv ON bs.SKU_GROUP = inv.SKU_GROUP AND bs.date = inv.date LEFT JOIN sales_fact sf ON bs.SKU_GROUP = sf.SKU_GROUP AND bs.date = sf.date LEFT JOIN overall_returns_fact orf ON bs.SKU_GROUP = orf.SKU_GROUP AND bs.date = orf.date LEFT JOIN shopify_returns_fact srf ON bs.SKU_GROUP = srf.SKU_GROUP AND bs.date = srf.date LEFT JOIN inward_fact ifw ON bs.SKU_GROUP = ifw.SKU_GROUP AND bs.date = ifw.date LEFT JOIN clicks_fact cf ON bs.SKU_GROUP = cf.SKU_GROUP AND bs.date = cf.date LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( IFF( UPPER(REPLACE(bs.SKU_GROUP,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(bs.SKU_GROUP,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'), \'-\', 2), SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'), \'-\', 1) ) ) ) , ff as (SELECT date, SKU_GROUP, l1_category, category, meta1, meta2, meta3, inventory_qty, inventory_cogs_value, revenue, sales_qty, sales_cogs, overall_returns_qty, overall_returns_cogs, shopify_returns_qty, shopify_returns_cogs, inward_qty, inward_cogs, clicks, SUM(revenue) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_revenue, SUM(sales_qty) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_sales_qty, SUM(sales_cogs) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_sales_cogs, SUM(overall_returns_qty) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_overall_returns_qty, SUM(overall_returns_cogs) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_overall_returns_cogs, SUM(shopify_returns_qty) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_returns_qty, SUM(shopify_returns_cogs) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_shopify_returns_cogs, SUM(inward_qty) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_inward_qty, SUM(inward_cogs) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_inward_cogs, SUM(clicks) OVER (PARTITION BY SKU_GROUP ORDER BY date ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS l30d_clicks FROM daily_grain ORDER BY 1, 2 ) select * from ff ;",
                    "transaction": true
                }
            ) }}
